#include <iostream>#include <string>using namespace std;class Address {    string city;    int pin;public:    Address(string c, int p) : city(c), pin(p) {}    void display() {        cout << city << "-" << pin << endl;    }};class Person {protected:    string name;    int age;public:    Person(string n, int a) : name(n), age(a) {        cout << "Person Constructor" << endl;    }    ~Person() {        cout << "Person Destructor" << endl;    }};class Student : public Person {    long long regNo;    Address home;public:    Student(string n, int a, long long r, string c, int p)        : Person(n, a), regNo(r), home(c, p) {        cout << "Student Constructor" << endl;    }    void display() {        cout << regNo << " " << name << " " << age << endl;        home.display();    }    ~Student() {        cout << "Student Destructor" << endl;    }};int main() {    Student s("Kavya", 19, 192311001, "Salem", 636001);    s.display();    return 0;}